    "\u7ed9\u4f60\u4e24\u4e2a\u5b57\u7b26\u4e32\u00a0s \u548c\u00a0t\u00a0\uff0c\u8bf7\u4f60\u627e\u51fa s\u00a0\u4e2d\u7684\u975e\u7a7a\u5b50\u4e32\u7684\u6570\u76ee\uff0c\u8fd9\u4e9b\u5b50\u4e32\u6ee1\u8db3\u66ff\u6362 \u4e00\u4e2a\u4e0d\u540c\u5b57\u7b26\u00a0\u4ee5\u540e\uff0c\u662f t\u00a0\u4e32\u7684\u5b50\u4e32\u3002\u6362\u8a00\u4e4b\uff0c\u8bf7\u4f60\u627e\u5230 s\u00a0\u548c t\u00a0\u4e32\u4e2d \u6070\u597d\u00a0\u53ea\u6709\u4e00\u4e2a\u5b57\u7b26\u4e0d\u540c\u7684\u5b50\u5b57\u7b26\u4e32\u5bf9\u7684\u6570\u76ee\u3002\n\n\u6bd4\u65b9\u8bf4\uff0c\u00a0\"computer\"\u00a0and\u00a0\"computation\"\u00a0\u53ea\u6709\u4e00\u4e2a\u5b57\u7b26\u4e0d\u540c\uff1a\u00a0'e'/'a'\u00a0\uff0c\u6240\u4ee5\u8fd9\u4e00\u5bf9\u5b50\u5b57\u7b26\u4e32\u4f1a\u7ed9\u7b54\u6848\u52a0 1 \u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u6ee1\u8db3\u4e0a\u8ff0\u6761\u4ef6\u7684\u4e0d\u540c\u5b50\u5b57\u7b26\u4e32\u5bf9\u6570\u76ee\u3002\n\n\u4e00\u4e2a \u5b50\u5b57\u7b26\u4e32\u00a0\u662f\u4e00\u4e2a\u5b57\u7b26\u4e32\u4e2d\u8fde\u7eed\u7684\u5b57\u7b26\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1as = \"aba\", t = \"baba\"\n\u8f93\u51fa\uff1a6\n\u89e3\u91ca\uff1a\u4ee5\u4e0b\u4e3a\u53ea\u76f8\u5dee 1 \u4e2a\u5b57\u7b26\u7684 s \u548c t \u4e32\u7684\u5b50\u5b57\u7b26\u4e32\u5bf9\uff1a\n(\"aba\", \"baba\")\n(\"aba\", \"baba\")\n(\"aba\", \"baba\")\n(\"aba\", \"baba\")\n(\"aba\", \"baba\")\n(\"aba\", \"baba\")\n\u52a0\u7c97\u90e8\u5206\u5206\u522b\u8868\u793a s \u548c t \u4e32\u9009\u51fa\u6765\u7684\u5b50\u5b57\u7b26\u4e32\u3002\n```\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1as = \"ab\", t = \"bb\"\n\u8f93\u51fa\uff1a3\n\u89e3\u91ca\uff1a\u4ee5\u4e0b\u4e3a\u53ea\u76f8\u5dee 1 \u4e2a\u5b57\u7b26\u7684 s \u548c t \u4e32\u7684\u5b50\u5b57\u7b26\u4e32\u5bf9\uff1a\n(\"ab\", \"bb\")\n(\"ab\", \"bb\")\n(\"ab\", \"bb\")\n\u52a0\u7c97\u90e8\u5206\u5206\u522b\u8868\u793a s \u548c t \u4e32\u9009\u51fa\u6765\u7684\u5b50\u5b57\u7b26\u4e32\u3002\n```\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1as = \"a\", t = \"a\"\n\u8f93\u51fa\uff1a0\n```\n\n\u793a\u4f8b 4\uff1a\n\n```\n\u8f93\u5165\uff1as = \"abe\", t = \"bbc\"\n\u8f93\u51fa\uff1a10\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= s.length, t.length <= 100\n\n\ts \u548c\u00a0t\u00a0\u90fd\u53ea\u5305\u542b\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3001t\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def countSubstrings(self, s: str, t: str) -> int:\n        ans = 0\n        for i in range(len(s)):\n            for j in range(len(t)):\n                diff = 0\n                k = 0\n                while i + k < len(s) and j + k < len(t):\n                    if s[i + k] != t[j + k]:\n                        diff += 1\n                    if diff == 1:\n                        ans += 1\n                    elif diff > 1:\n                        break\n                    k += 1\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.countSubstrings(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int",
